// Canonical HMAC SHA-256 Signature Verification
const crypto = require('crypto');

function canonicalStringify(obj) {
  if (obj === null || typeof obj !== 'object') {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return '[' + obj.map(canonicalStringify).join(',') + ']';
  }
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStringify(obj[k])).join(',') + '}';
}

const secret = $env.N8N_WEBHOOK_SECRET || 'your-32-character-secure-hmac-secret-here';
const headers = $node['Webhook Ingest'].json.headers;
const signature = headers['x-st-signature'];
const timestamp = headers['x-st-timestamp'];
const deliveryId = headers['x-st-delivery-id'] || $input.item.json.deliveryId;

if (!signature || !timestamp || !deliveryId) {
  throw new Error('Missing required security headers');
}

const canonicalPayload = canonicalStringify($input.item.json);
const stringToSign = `${timestamp}.${deliveryId}.${canonicalPayload}`;
const calculated = crypto.createHmac('sha256', secret).update(stringToSign).digest('hex');

if (signature !== calculated) {
  throw new Error('HMAC signature verification failed: Invalid payload signature');
}

return $input.item;

// Build authenticated callback payload to report DELIVERED status
const crypto = require('crypto');

function canonicalStringify(obj) {
  if (obj === null || typeof obj !== 'object') {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return '[' + obj.map(canonicalStringify).join(',') + ']';
  }
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalStringify(obj[k])).join(',') + '}';
}

const secret = $env.N8N_WEBHOOK_SECRET || 'your-32-character-secure-hmac-secret-here';
const deliveryId = $node['Verify Canonical Signature'].json.deliveryId;
const callbackUrl = $node['Verify Canonical Signature'].json.callbackUrl || 'http://localhost:3000/api/v1/automation/callback';
const timestamp = new Date().toISOString();

const callbackBody = {
  deliveryId: deliveryId,
  status: 'DELIVERED',
  responseCode: 200,
  providerMessageId: 'n8n-subscriber-' + Date.now(),
  deliveredAt: timestamp
};

const canonical = canonicalStringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${deliveryId}.${canonical}`).digest('hex');

return [{
  json: {
    callbackUrl,
    callbackBody,
    headers: {
      'Content-Type': 'application/json',
      'X-ST-Signature': signature,
      'X-ST-Timestamp': timestamp,
      'X-ST-Delivery-Id': deliveryId
    }
  }
}];
